import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"復","description":"周易正義 - 復","frontmatter":{"title":"復","description":"周易正義 - 復"},"headers":[],"relativePath":"classics/zhengyi/024.md","filePath":"classics/zhengyi/024.md"}'),l={name:"classics/zhengyi/024.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>地雷復</p></blockquote><blockquote><p>卦辭：亨。出入無疾，朋來無咎。反覆其道，七日來複，利有攸往。</p></blockquote><blockquote><p>彖曰：復，亨。剛反，動而以順行。是以出入無疾，朋來無咎。反覆其道，七日來複，天行也。利有攸往，剛長也。復，其見天地之心乎。</p></blockquote><h1 id="復" tabindex="-1">復 <a class="header-anchor" href="#復" aria-label="Permalink to “復”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“復亨”者，陽氣反覆而得亨通，故云“復亨”也。“出入無疾”者，出則剛長，入則陽反，理會其時，故無疾病也。“朋來無咎”者，朋謂陽也。反覆眾陽，朋聚而來，則“無咎”也。若非陽眾來，則有咎，以其眾陽之來，故“無咎”也。“反覆其道，七日來複”者，欲速反之與復而得其道，不可過遠。唯七日則來複，乃合於道也。“利有攸往”者，以陽氣方長，往則小人道消，故“利有攸往”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="復-亨-剛反動而以順行-是以-出入無疾-​" tabindex="-1">“復，亨”，剛反動而以順行，是以“出入無疾”， ​ <a class="header-anchor" href="#復-亨-剛反動而以順行-是以-出入無疾-​" aria-label="Permalink to ““復，亨”，剛反動而以順行，是以“出入無疾”， ​”">​</a></h3><p>王弼：入則為反，出則剛長，故“無疾”。疾猶病也。“朋來無咎”，“朋”謂陽也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“彖曰”至“無咎”。○正義曰：“復亨”者，以陽復則亨，故以亨連復而釋之也。“剛反動而以順行”者，既上釋“復亨”之義，又下釋“出入無疾朋來無咎”之理，故云“是以出入無疾朋來無咎”也。</p><h3 id="反覆其道-七日來複-​" tabindex="-1">“反覆其道，七日來複 ​ <a class="header-anchor" href="#反覆其道-七日來複-​" aria-label="Permalink to ““反覆其道，七日來複 ​”">​</a></h3><p>王弼：”陽氣始剝盡至來複時，凡七日。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“陽氣始剝盡”，謂陽氣始於剝盡之後，至陽氣來複時，凡經七日。觀《注》之意，陽氣從剝盡之後，至於反覆，凡經七日。其《注》分明。如褚氏、莊氏並雲“五月一陰生，至十一月一陽生”，凡七月。而云“七日”，不雲“月”者，欲見陽長鬚速，故變月言日。今輔嗣雲“剝盡”至“來複”，是從盡至來複，經七日也。若從五月言之，何得雲“始盡”也？又臨卦亦是陽長而言八月，今《復卦》亦是陽長，何以獨變月而稱七日？觀《注》之意，必謂不然，亦用《易緯》六日七分之義，同鄭康成之說。但於文省略，不復具言。案《易緯稽覽圖》雲：“卦氣起中孚。”故離、坎、震、兌，各主其一方，其餘六十卦，卦有六爻，爻別主一日，凡主三百六十日。餘有五日四分日之一者，每日分為八十分，五日分為四百分四分日之一又為二十分，是四百二十分。六十卦分之，六七四十二卦，別各得七分，是每卦得六日七分也。剝卦陽氣之盡在於九月之末，十月當純坤用事。坤卦有六日七分。坤卦之盡，則復卦陽來，是從剝盡至陽氣來複，隔坤之一卦六日七分，舉成數言之，故輔嗣言“凡七日”也。“反覆”者，則出入之義。反謂入而倒反覆謂既反，之後復而向上也。</p><h3 id="天行也。-​" tabindex="-1">天行也。 ​ <a class="header-anchor" href="#天行也。-​" aria-label="Permalink to “天行也。 ​”">​</a></h3><p>王弼：以天之行，反覆不過七日，復之不可遠也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“反覆其道，七日來複。天行”者，以天行釋“反覆其道七日來複”之義。言反之與復得合其道。唯七日而來複，不可久遠也。此是天之所行也。天之陽氣絕滅之後，不過七日，陽氣復生，此乃天之自然之理，故曰“天行”也。</p><h3 id="利有攸往-剛長也。-​" tabindex="-1">“利有攸往”，剛長也。 ​ <a class="header-anchor" href="#利有攸往-剛長也。-​" aria-label="Permalink to ““利有攸往”，剛長也。 ​”">​</a></h3><p>王弼：往則小人道消也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“以剛長”釋“利有攸往”之義也。</p><h3 id="復-其見天地之心乎。-​" tabindex="-1">復，其見天地之心乎。 ​ <a class="header-anchor" href="#復-其見天地之心乎。-​" aria-label="Permalink to “復，其見天地之心乎。 ​”">​</a></h3><p>王弼：復者，反本之謂也，天地以本為心者也。凡動息則靜，靜非對動者也。語息則默，默非對語者也。然則天地雖大，富有萬物，雷動風行，運化萬變，寂然至無，是其本矣。故動息地中，乃天地之心見也。若其以有為心，則異類未獲具存矣。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>“復見天地之心乎”。○正義曰：“復其見天地之心乎”者，此贊明覆卦之義。天地養萬物，以靜為心，不為而物自為，不生而物自生，寂然不動，此天地之心也。此復卦之象，“動”息地中，雷在地下，息而不動，靜寂之義，與天地之心相似。觀此復象，乃“見天地之心”也。天地非有主宰，何得有心？以人事之心，託天地以示法爾。○注“復者反本之謂也”至“未獲具存矣”。○正義曰：“復者反本之謂也”者，往前離本處而去，今更反於本處，是“反本”之謂也。“天地以本為心”者，“本”謂靜也。言天地寂然不動，是“以本為心”者也。凡動息則靜，靜非對動者也。天地之動，靜為其本，動為其末，言靜時多也，動時少也。若暫時而動，止息則歸靜，是靜非對動，言靜之為本，自然而有，非對動而生靜，故曰“靜非對動”者也。“語息則默，默非對語”者，語則聲之動，默則口之靜，是不語之時，恆常默也。非是對語有默以動靜語默，而地別體，故云“非對”也。雲“天地雖大，富有萬物，雷動風行，運化萬變”者，此言天地之動也。言“寂然至無是其本矣”者，凡有二義：一者萬物雖運動於外，而天地寂然至於其內也。外是其末，內是其本，言天地無心也。二者雖雷動風行，千化萬變，若其雷風止息，運化停住之後，亦寂然至無也。“若其以有為心，則異類未獲具存”者，凡以無為心，則物我齊致，親疏一等，則不害異類，彼此獲寧。若其以有為心，則我之自我，不能普及於物，物之自物，不能普賴於我，物則被害，故“未獲具存”也。</p><h2 id="《象》曰-雷在地中-復。先王以至日閉關-商旅不行-後不省方。-​" tabindex="-1">《象》曰：雷在地中，復。先王以至日閉關，商旅不行，後不省方。 ​ <a class="header-anchor" href="#《象》曰-雷在地中-復。先王以至日閉關-商旅不行-後不省方。-​" aria-label="Permalink to “《象》曰：雷在地中，復。先王以至日閉關，商旅不行，後不省方。 ​”">​</a></h2><p>王弼：方，事也。冬至，陰之復也。夏至，陽之復也。故為復則至於寂然大靜，先王則天地而行者也。動復則靜，行復則止，事復則無事也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“後不省方”。○正義曰：“雷在地中復”者，雷是動物，復卦以動息為主，故曰“雷在地中”。“先王以至日閉關”者，先王象此復卦，以二至之日閉塞其關，使商旅不行於道路也。“後不省方”者，方，事也。後不省視其方事也。以地掩閉於雷，故關門掩閉，商旅不行。君後掩閉於事，皆取“動息”之義。○注“方事也”至“事復則無事也”。○正義曰：“方，事”者，恐“方”是四方境域，故以“方”為事也。言至日不但不可出行，亦不可省視事也。“冬至陰之復，夏至陽之復”者，復謂反本，靜為動本。冬至一陽生，是陽動用而陰復於靜也。夏至一陰生，是陰動用而陽復於靜也。“動復則靜，行復則止，事復則無事”者，動而反覆則歸靜，行而反覆則歸止，事而反覆則歸於無事也。</p><h2 id="初九-不遠復-無祗悔-元吉。-​" tabindex="-1">初九：不遠復，無祗悔，元吉。 ​ <a class="header-anchor" href="#初九-不遠復-無祗悔-元吉。-​" aria-label="Permalink to “初九：不遠復，無祗悔，元吉。 ​”">​</a></h2><p>王弼：最處復初，始復者也。復之不速，遂至迷兇，不遠而復，幾悔而反，以此修身，患難遠矣。錯之於事，其始庶幾乎？故“元吉”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“不遠復”者，最處復初，是始復者也。既在陽復，即能從而復之，是迷而不遠，即能復也。“無祗悔元吉”者，韓氏雲：“祗，大也。”既能速復，是無大悔，所以大吉。</p><h3 id="《象》曰-不遠-之復-以脩身也。-​" tabindex="-1">《象》曰：“不遠”之復，以脩身也。 ​ <a class="header-anchor" href="#《象》曰-不遠-之復-以脩身也。-​" aria-label="Permalink to “《象》曰：“不遠”之復，以脩身也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“釋不遠之復”也。所以不遠速復者，以能脩正其身，有過則改故也。</p><h2 id="六二-休復-吉。-​" tabindex="-1">六二：休復，吉。 ​ <a class="header-anchor" href="#六二-休復-吉。-​" aria-label="Permalink to “六二：休復，吉。 ​”">​</a></h2><p>王弼：得位處中，最比於初。上無陽爻以疑其親，陽為仁行，在初之上而附順之，下仁之謂也。既處中位，親仁善鄰，復之休也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：得位處中，最比於初，陽為仁行，已在其上，附而順之，是降下於仁，是休美之復，故云“休復吉”也。以其下仁，所以“吉”也。故《象》雲“休復之吉，以下仁也”。</p><h3 id="《象》曰-休復-之吉-以下仁也。-​" tabindex="-1">《象》曰：“休復”之吉，以下仁也。 ​ <a class="header-anchor" href="#《象》曰-休復-之吉-以下仁也。-​" aria-label="Permalink to “《象》曰：“休復”之吉，以下仁也。 ​”">​</a></h3><h2 id="六三-頻復-厲無咎。-​" tabindex="-1">六三：頻復，厲無咎。 ​ <a class="header-anchor" href="#六三-頻復-厲無咎。-​" aria-label="Permalink to “六三：頻復，厲無咎。 ​”">​</a></h2><p>王弼：頻，頻蹙之貌也。處下體之終，雖愈於上六之迷，巳失復遠矣，是以蹙也。蹙而求復，未至於迷，故雖危無咎也。複道宜速，蹙而乃復，義雖無咎，它來難保。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰休復之吉”至“無咎”。○正義曰：“頻復”者，頻謂頻蹙。六三處下體之上，去復稍遠，雖勝於上六迷復，猶頻蹙而復，複道宜速，謂蹙而求復也。去復猶近，雖有危厲，於義無咎。故《象》雲“義無咎”也。注“頻蹙之貌”至“它來難保”。○正義曰：“義雖無咎，它來難保”者，去復未甚大遠，於義雖復無咎，謂以道自守，得“無咎”也。若自守之外，更有他事而來，則難可保此無咎之吉也。所以《象》雲“義無咎”，守常之義得無咎也。</p><h3 id="《象》曰-頻復-之厲-義無咎也。-​" tabindex="-1">《象》曰：“頻復”之厲，義無咎也。 ​ <a class="header-anchor" href="#《象》曰-頻復-之厲-義無咎也。-​" aria-label="Permalink to “《象》曰：“頻復”之厲，義無咎也。 ​”">​</a></h3><h2 id="六四-中行獨復。-​" tabindex="-1">六四：中行獨復。 ​ <a class="header-anchor" href="#六四-中行獨復。-​" aria-label="Permalink to “六四：中行獨復。 ​”">​</a></h2><p>王弼：四上下各有二陰而處厥中，履得其位而應於初，獨得所復，順道而反，物莫之犯，故曰“中行獨復”也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“中行獨復”。○正義曰：“中行獨復”者，處於上卦之下，上下各有二陰，巳獨應初，居在眾陰之中，故云“中行”。獨自應初，故云“獨復”。從道而歸，故《象》雲“以從道也”。</p><h3 id="《象》曰-中行獨復-以從道也。-​" tabindex="-1">《象》曰：“中行獨復”，以從道也。 ​ <a class="header-anchor" href="#《象》曰-中行獨復-以從道也。-​" aria-label="Permalink to “《象》曰：“中行獨復”，以從道也。 ​”">​</a></h3><h2 id="六五-敦復-無悔。-​" tabindex="-1">六五：敦復，無悔。 ​ <a class="header-anchor" href="#六五-敦復-無悔。-​" aria-label="Permalink to “六五：敦復，無悔。 ​”">​</a></h2><p>王弼：居厚而履中，居厚則無怨，履中則可以自考，雖不足以及“休復”之吉，守厚以復，悔可免也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“敦復無悔”者，處坤之中，是敦厚於復，故云“敦復”。既能履中，又能自考成其行。既居敦厚物，無所怨，雖不及六二之“休復”，猶得免於悔吝，故云“無悔”也。</p><h3 id="《象》曰-敦復-無悔-中以自考也。-​" tabindex="-1">《象》曰：“敦復，無悔”，中以自考也。 ​ <a class="header-anchor" href="#《象》曰-敦復-無悔-中以自考也。-​" aria-label="Permalink to “《象》曰：“敦復，無悔”，中以自考也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“無悔”之義。以其處中，能自考其身，故“無悔”也。</p><h2 id="上六-迷復-兇-有災眚。用行師-終有大敗。以其國君兇-至於十年不克徵。-​" tabindex="-1">上六：迷復，兇，有災眚。用行師，終有大敗。以其國君兇，至於十年不克徵。 ​ <a class="header-anchor" href="#上六-迷復-兇-有災眚。用行師-終有大敗。以其國君兇-至於十年不克徵。-​" aria-label="Permalink to “上六：迷復，兇，有災眚。用行師，終有大敗。以其國君兇，至於十年不克徵。 ​”">​</a></h2><p>王弼：最處復後，是迷者也。以迷求復，故曰“迷復”也。用之行師，難用有克也，終必大敗。用之於國，則反乎君道也。大敗乃復量斯勢也。雖復十年修之，猶未能徵也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>“上六迷復兇”至“不克徵”。○正義曰：“迷復兇”者，最處復後，是迷闇於復。“以迷求復”，所以“兇”也。“有災眚”者，闇於複道，必無福慶，唯有災眚也。“用行師終有大敗”者，所為既兇，故用之行師，必無克勝，唯“終有大敗”也。“以其國君兇”者，以，用也。用此迷復於其國內，則反違君道，所以兇也。“至於十年不克徵”者，師敗國兇，量斯形勢，雖至十年猶不能征伐。以其迷闇不復，而反違於君道，故《象》雲“迷復之兇，反君道也”。</p><h3 id="《象》曰-迷復-之兇-反君道也。-​" tabindex="-1">《象》曰：“迷復”之兇，反君道也。 ​ <a class="header-anchor" href="#《象》曰-迷復-之兇-反君道也。-​" aria-label="Permalink to “《象》曰：“迷復”之兇，反君道也。 ​”">​</a></h3>',65)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
